      pt: ["Local na província da Zambézia.", "Localização no interior.", "Clima quente e húmido.", "Zona envolvente de cariz agrícola.", "Importante local de distrito e de mercado.", "Centro de abastecimento para aldeias."],
      fr: ["Localité de la province de Zambézie.", "Situation à l'intérieur des terres.", "Climat chaud et humide.", "Environs à vocation agricole.", "Importante localité de district et de marché.", "Centre de ravitaillement pour les villages."],
